import copy
import json
import sys

ROOT_FIELDS = {"resourceId", "maps"}
MAP_FIELDS = {"name", "expectedIds", "claims"}
CLAIM_FIELDS = {
    "Claim ID", "Atomic claim", "Type", "Scope", "Materiality",
    "Evidence needed", "Source or evidence ID", "Support",
    "Confidence and reason", "Depends on", "Disposition"
}
TYPES = {"FACT", "DEFINITION", "COMPARISON", "CAUSAL", "PREDICTION", "RECOMMENDATION", "VALUE"}
MATERIALITY = {"LOW", "MEDIUM", "HIGH"}
SUPPORT = {"DIRECT", "INFERRED", "CONTRADICTED", "UNKNOWN"}
DISPOSITION = {"KEEP", "QUALIFY", "REMOVE", "ESCALATE"}


def fields_error(value, required, path, errors):
    if not isinstance(value, dict):
        errors.append(path + " must be an object")
        return False
    missing = required - set(value)
    extra = set(value) - required
    if missing:
        errors.append(path + " missing fields: " + ", ".join(sorted(missing)))
    if extra:
        errors.append(path + " extra fields: " + ", ".join(sorted(extra)))
    return not missing and not extra


def valid_enum(value, allowed):
    return isinstance(value, str) and value in allowed


def validate_document(document):
    errors = []
    if not fields_error(document, ROOT_FIELDS, "root", errors):
        if not isinstance(document, dict):
            return errors
    if document.get("resourceId") != "claim-decomposition-map":
        errors.append("root.resourceId must be claim-decomposition-map")
    maps = document.get("maps")
    if not isinstance(maps, list) or not maps:
        errors.append("root.maps must be a nonempty list")
        return errors

    map_names = []
    for map_index, claim_map in enumerate(maps):
        path = "maps[{}]".format(map_index)
        if not fields_error(claim_map, MAP_FIELDS, path, errors):
            if not isinstance(claim_map, dict):
                continue
        name = claim_map.get("name")
        if not isinstance(name, str) or not name.strip():
            errors.append(path + ".name must be a nonempty string")
            name = "<invalid>"
        map_names.append(name)
        expected = claim_map.get("expectedIds")
        if not isinstance(expected, list) or any(not isinstance(item, str) or not item.strip() for item in expected):
            errors.append(path + ".expectedIds must be a list of nonempty strings")
            expected = []
        if len(expected) != len(set(expected)):
            errors.append(path + ".expectedIds contains duplicates")

        claims = claim_map.get("claims")
        if not isinstance(claims, list) or not claims:
            errors.append(path + ".claims must be a nonempty list")
            continue

        ids = []
        graph = {}
        for claim_index, claim in enumerate(claims):
            cpath = path + ".claims[{}]".format(claim_index)
            if not fields_error(claim, CLAIM_FIELDS, cpath, errors):
                if not isinstance(claim, dict):
                    continue
            claim_id = claim.get("Claim ID")
            if not isinstance(claim_id, str) or not claim_id.strip():
                errors.append(cpath + ".Claim ID must be a nonempty string")
                continue
            ids.append(claim_id)
            for field in ("Atomic claim", "Scope", "Evidence needed", "Confidence and reason"):
                if not isinstance(claim.get(field), str) or not claim.get(field).strip():
                    errors.append(claim_id + " has empty or malformed " + field)
            for field, allowed in (
                ("Type", TYPES),
                ("Materiality", MATERIALITY),
                ("Support", SUPPORT),
                ("Disposition", DISPOSITION),
            ):
                if not valid_enum(claim.get(field), allowed):
                    errors.append(claim_id + " has invalid " + field)
            dependencies = claim.get("Depends on")
            if not isinstance(dependencies, list) or any(not isinstance(item, str) or not item.strip() for item in dependencies):
                errors.append(claim_id + " Depends on must be a list of nonempty strings")
                dependencies = []
            if len(dependencies) != len(set(dependencies)):
                errors.append(claim_id + " has duplicate dependencies")
            graph[claim_id] = dependencies
            materiality = claim.get("Materiality")
            if isinstance(materiality, str) and materiality in {"MEDIUM", "HIGH"}:
                evidence = claim.get("Source or evidence ID")
                if not isinstance(evidence, str) or not evidence.strip():
                    errors.append("missing material claim coverage: " + claim_id)

        if len(ids) != len(set(ids)):
            errors.append(path + " contains duplicate claim IDs")
        actual_set = set(ids)
        expected_set = set(expected)
        missing_ids = expected_set - actual_set
        extra_ids = actual_set - expected_set
        if missing_ids:
            errors.append(path + " missing expected claim IDs: " + ", ".join(sorted(missing_ids)))
        if extra_ids:
            errors.append(path + " has extra claim IDs: " + ", ".join(sorted(extra_ids)))
        for claim_id, dependencies in graph.items():
            for dependency in dependencies:
                if dependency not in actual_set:
                    errors.append(claim_id + " refers to missing dependency " + dependency)

        state = {}
        cycle_reports = set()
        def visit(node, trail):
            status = state.get(node, 0)
            if status == 1:
                start = trail.index(node) if node in trail else 0
                cycle = trail[start:] + [node]
                text = " -> ".join(cycle)
                if text not in cycle_reports:
                    cycle_reports.add(text)
                    errors.append("dependency cycle: " + text)
                return
            if status == 2:
                return
            state[node] = 1
            for dependency in graph.get(node, []):
                if dependency in graph:
                    visit(dependency, trail + [node])
            state[node] = 2
        for claim_id in graph:
            visit(claim_id, [])

    if len(map_names) != len(set(map_names)):
        errors.append("duplicate map name")
    required_maps = {"worked", "changed"}
    missing_maps = required_maps - set(map_names)
    if missing_maps:
        errors.append("missing required maps: " + ", ".join(sorted(missing_maps)))
    return errors


def expect_failure(base, label, mutate, expected_text):
    candidate = copy.deepcopy(base)
    candidate = mutate(candidate)
    errors = validate_document(candidate)
    if not errors:
        raise AssertionError(label + " unexpectedly passed")
    if not any(expected_text in error for error in errors):
        raise AssertionError(label + " lacked expected diagnostic: " + expected_text + "; got " + repr(errors))


def run_self_tests(base):
    if validate_document(base):
        raise AssertionError("valid worked and changed fixtures failed")

    def duplicate_id(doc):
        doc["maps"][0]["claims"].append(copy.deepcopy(doc["maps"][0]["claims"][0]))
        return doc
    def empty_id(doc):
        doc["maps"][0]["claims"][0]["Claim ID"] = ""
        return doc
    def missing_claim(doc):
        doc["maps"][0]["claims"].pop()
        return doc
    def extra_claim(doc):
        item = copy.deepcopy(doc["maps"][0]["claims"][0])
        item["Claim ID"] = "C-999"
        doc["maps"][0]["claims"].append(item)
        return doc
    def missing_coverage(doc):
        doc["maps"][0]["claims"][0]["Source or evidence ID"] = ""
        return doc
    def dangling_dependency(doc):
        doc["maps"][0]["claims"][0]["Depends on"] = ["C-NOT-THERE"]
        return doc
    def cycle(doc):
        doc["maps"][0]["claims"][0]["Depends on"] = ["C-002"]
        return doc
    def malformed_nested(doc):
        doc["maps"][0]["claims"][0] = []
        return doc
    def invalid_enum(doc):
        doc["maps"][0]["claims"][0]["Support"] = "MAYBE"
        return doc
    def malformed_root(doc):
        return []
    def invalid_enum_type(field, value):
        def mutate(doc):
            doc["maps"][0]["claims"][0][field] = value
            return doc
        return mutate

    cases = [
        ("duplicate ID", duplicate_id, "duplicate claim IDs"),
        ("empty ID", empty_id, "Claim ID must be a nonempty string"),
        ("missing expected coverage", missing_claim, "missing expected claim IDs"),
        ("extra coverage", extra_claim, "extra claim IDs"),
        ("missing material evidence", missing_coverage, "missing material claim coverage"),
        ("dangling dependency", dangling_dependency, "refers to missing dependency"),
        ("dependency cycle", cycle, "dependency cycle"),
        ("malformed nested claim", malformed_nested, "must be an object"),
        ("invalid enum", invalid_enum, "invalid Support"),
        ("malformed top level", malformed_root, "root must be an object"),
    ]
    for field in ("Type", "Materiality", "Support", "Disposition"):
        for label, value in (("list", []), ("dict", {}), ("null", None)):
            cases.append((
                "{} enum {} value".format(field, label),
                invalid_enum_type(field, value),
                "invalid " + field,
            ))
    for label, mutation, expected in cases:
        expect_failure(base, label, mutation, expected)
    print("SELF-TEST PASS: valid worked and changed maps plus 22 negative cases")


def main(argv):
    if len(argv) not in {2, 3} or (len(argv) == 3 and argv[2] != "--self-test"):
        print("Usage: python3 checker.py claim_maps.json [--self-test]")
        return 2
    try:
        with open(argv[1], "r", encoding="utf-8") as handle:
            document = json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        print("FAIL: could not read valid JSON: " + str(error))
        return 1
    errors = validate_document(document)
    if errors:
        print("FAIL")
        for error in errors:
            print(error)
        return 1
    print("PASS: structure, IDs, enums, expected coverage, dependency references, and cycles only")
    if len(argv) == 3:
        try:
            run_self_tests(document)
        except AssertionError as error:
            print("SELF-TEST FAIL: " + str(error))
            return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
